"""Bitwise OR for tensors (aten::__or__.Tensor / bitwise_or.Tensor).

Hand-written Triton implementation:

  * flat grid-stride kernel for the common case (equal shapes, contiguous
    operands, contiguous output),
  * generic grid-stride strided kernel for broadcasts / non-contiguous
    operands: one masked flat index into the (contiguous) output is decomposed
    into the logical coordinates of the broadcast output and dotted with each
    operand's own stride vector (stride 0 on broadcast axes),
  * scalar variants for ``tensor | python_int``.

The device reports a hard ``grid.x`` limit of 65535 programs, so every kernel
uses a grid-stride loop: ``grid = min(cdiv(numel, BLOCK), 65535)``.

All value computation happens in device kernels; the wrapper only allocates the
output, reads metadata (shape/stride/dtype) and computes the launch grid.
"""

import logging

import torch
import triton
import triton.language as tl

logger = logging.getLogger(__name__)

# BLOCK is the per-lane DMA width (threads-per-warp = 1 on this backend), so it
# has to be picked per element size: the tile BYTES are what set bandwidth.
# Swept on gcu:2 with triton.testing.do_bench (the harness timer for this op),
# bool (1 byte) 16.7M elements: BLOCK 16384 -> 295 GB/s, 32768 -> 371,
# 65536 -> 380 (torch 397); 1G bool: 338 -> 438 -> 440 GB/s (torch 438).
# int16/int32 are already at ~406-426 GB/s with 16384 and 65536 does not help
# them (int32 65536 even regresses 1%), so only 1-byte operands get the wider
# tile.
_BLOCK = 16384
_BLOCK_BYTE = 65536
_NUM_WARPS = 1
_MAX_DIMS = 8
_MAX_GRID = 48


@triton.jit
def _or_flat_kernel(a_ptr, b_ptr, o_ptr, n, nprog, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    dt = o_ptr.dtype.element_ty
    ar = tl.arange(0, BLOCK)
    step = nprog * BLOCK
    off = pid * BLOCK
    while off < n:
        offs = off + ar
        mask = offs < n
        a = tl.load(a_ptr + offs, mask=mask).to(dt)
        b = tl.load(b_ptr + offs, mask=mask).to(dt)
        tl.store(o_ptr + offs, a | b, mask=mask)
        off += step


