_PROMO_CACHE = {}


def _promoted(da, db):
    if da is db:
        return da
    key = (da, db)
    r = _PROMO_CACHE.get(key)
    if r is None:
        r = torch.promote_types(da, db)
        _PROMO_CACHE[key] = r
    return r


def _layout(shape, stride_lists):
    """Drop size-1 axes and merge adjacent axes that stay contiguous for *all*
    operands, so every operand ends up with the same axis count.

    Returns (dims, [strides_per_operand]).
    """
    dims = []
    strs = [[] for _ in stride_lists]
    for i, d in enumerate(shape):
        if d == 1:
            continue
        dims.append(d)
        for k, sl in enumerate(stride_lists):
            strs[k].append(sl[i])
    i = 0
    while i + 1 < len(dims):
        if all(st[i] == st[i + 1] * dims[i + 1] for st in strs):
            dims[i] = dims[i] * dims[i + 1]
            for st in strs:
                st[i] = st[i + 1]
                del st[i + 1]
            del dims[i + 1]
        else:
            i += 1
    return dims, strs


def _pad(vals, fill):
    return [fill] * (_MAX_DIMS - len(vals)) + list(vals)


def _block_for(dtype, n):
    blk = _BLOCK_BYTE if dtype.itemsize == 1 else _BLOCK
    while blk > n and blk > 64:
        blk //= 2  # launch-bound sizes: an exact tile beats a masked one
    return blk


def _grid(n, block):
    # 48 persistent programs x BLOCK-element tiles reaches the bandwidth
    # roofline on this backend; a wide grid only pays the per-program cost.
    g = (n + block - 1) // block
    if g > _MAX_GRID:
        g = _MAX_GRID
    return g if g > 0 else 1


def _tensor_tensor(a, b):
    if a.shape == b.shape:
        if a.is_contiguous() and b.is_contiguous():
            out = torch.empty(
                a.shape, dtype=_promoted(a.dtype, b.dtype), device=a.device
            )
            n = out.numel()
            blk = _block_for(out.dtype, n)
            g = _grid(n, blk)
            _or_flat_kernel[(g,)](a, b, out, n, g, BLOCK=blk, num_warps=_NUM_WARPS)
            return out
        shape = a.shape
        ea, eb = a, b
    else:
        shape = torch.broadcast_shapes(a.shape, b.shape)
        ea = a.expand(shape) if a.shape != shape else a
        eb = b.expand(shape) if b.shape != shape else b

    out = torch.empty(shape, dtype=_promoted(a.dtype, b.dtype), device=a.device)
    n = out.numel()
    dims, (sa, sb) = _layout(
        [d if d else 1 for d in shape], [list(ea.stride()), list(eb.stride())]
    )
    if len(dims) > _MAX_DIMS:
        raise RuntimeError("bitwise_or: operand rank too large")
    g = _grid(n, _block_for(out.dtype, n))
    _or_strided_kernel[(g,)](
        ea,
        eb,
        out,
        n,
        g,
        *_pad(dims, 1),
        *_pad(sa, 0),
        *_pad(sb, 0),
        BLOCK=_block_for(out.dtype, n),
        NDIM=len(dims),
        num_warps=_NUM_WARPS,
    )
    return out


def _tensor_scalar(x, val):
    out = torch.empty(x.shape, dtype=torch.result_type(x, val), device=x.device)
    n = out.numel()
    blk = _block_for(out.dtype, n)
    g = _grid(n, blk)
    if x.is_contiguous():
        _or_scalar_flat_kernel[(g,)](x, out, val, n, g, BLOCK=blk, num_warps=_NUM_WARPS)
        return out
    dims, (sx,) = _layout([d if d else 1 for d in x.shape], [list(x.stride())])
    if len(dims) > _MAX_DIMS:
        raise RuntimeError("bitwise_or: operand rank too large")
    _or_scalar_strided_kernel[(g,)](
        x,
        out,
        val,
        n,
        g,
        *_pad(dims, 1),
        *_pad(sx, 0),
        BLOCK=_block_for(out.dtype, n),
        NDIM=len(dims),
        num_warps=_NUM_WARPS,
    )
    return out


def or_tensor(self, other):
    logger.debug("GEMS OR_TENSOR")
    if torch.is_tensor(self):
        if torch.is_tensor(other):
            return _tensor_tensor(self, other)
        return _tensor_scalar(self, other)
    if torch.is_tensor(other):
        return _tensor_scalar(other, self)
    raise TypeError("bitwise_or: at least one operand must be a Tensor")
